// Expected body: { action:'kairikos_chatbot', publicToken, sessionId, message, timestamp }
const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').toString().trim();
const publicToken = (body.publicToken || '').toString().trim();
const sessionId = (body.sessionId || ('web-' + Date.now())).toString();
const errorCode = !publicToken ? 'missing_public_token' : (!message ? 'empty_message' : '');
return [{ json: { _error: errorCode, message, publicToken, sessionId } }];

// Traduce la respuesta del portal al contrato que espera el widget.
// El portal ya genero la respuesta con la configuracion aprobada, el
// historial y la base de conocimiento, y ya guardo los dos turnos: aqui
// solo se le da forma. Ver docs/plan-motor-chatbot.md.
const res = $input.first().json || {};
const input = $('Extract Input').first().json;
const contactIntent = /(cita|presupuesto|contacto|llamar|llamame|reuni[oó]n|hablar|contratar|me interesa|quiero|necesito|reservar|agendar|disponibilidad|horario|email|correo|tel[eé]fono|whatsapp)/i.test(input.message || '');

let reply = typeof res.reply === 'string' ? res.reply.trim() : '';
let mode = 'portal';
let errorDetail = null;

if (!reply) {
  if (res.handledBy === 'human') {
    // Una persona tiene la conversacion: el bot se calla a proposito.
    mode = 'human';
    reply = 'Ahora mismo te atiende una persona del equipo. Escribe aqui tu mensaje y lo vera enseguida.';
  } else if (res.reason === 'monthly_cap_reached') {
    // El chatbot agoto su tope de mensajes del mes (lib/chatbot-usage.ts).
    mode = 'cap';
    reply = 'Ahora mismo no puedo responderte por aqui. Dejanos tu consulta con un email o telefono y el equipo te contesta en breve.';
  } else {
    mode = 'fallback';
    errorDetail = res.error || res.detail || 'unknown';
    reply = contactIntent
      ? 'Gracias por escribir. Para ayudarte mejor, cuentame tu nombre y un email o telefono de contacto y el equipo te respondera en breve.'
      : 'Gracias por tu mensaje. Ahora mismo no puedo darte una respuesta detallada, pero el equipo lo revisara. Si quieres, dejame tus datos de contacto.';
  }
}

return [{ json: {
  sessionId: input.sessionId,
  publicToken: input.publicToken,
  reply,
  timestamp: new Date().toISOString(),
  mode,
  contactIntent,
  error: errorDetail,
  conversationId: res.conversationId || null,
} }];

const raw = $input.first().json;
const content = raw && raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content;
let parsed = null;
try { parsed = content ? JSON.parse(content) : null; } catch (e) { parsed = null; }
const isLead = Boolean(parsed && parsed.isLead === true);
const score = parsed && typeof parsed.score === 'number' ? Math.max(0, Math.min(100, Math.round(parsed.score))) : null;
return [{ json: {
  isLead,
  score,
  contactName: (parsed && parsed.contactName) || null,
  contactPhone: (parsed && parsed.contactPhone) || null,
  contactEmail: (parsed && parsed.contactEmail) || null,
  summary: (parsed && parsed.summary) || null,
} }];
